// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 blockNumberOffset) public {
        vm.assume(amount == 10 ether);
        // Ensure we can call fallback with increasing timestamps
        vm.assume(block.timestamp > c.pastBlockTime());

        // Record timestamp before call
        uint256 timeBefore = block.timestamp;

        // Drive the contract through the fallback
        (bool success, ) = address(c).call{value: amount}("");

        // After the call, check that pastBlockTime was updated
        // The rule: pastBlockTime must be at least timeBefore + 1
        assertTrue(success && c.pastBlockTime() >= timeBefore + 1);
    }
}

